#!/usr/bin/env python3
"""
Round 130b (culprits), 2 October 2026. Needs round 129b.

What drug and device companies pay doctors, US states by year (CMS Open Payments).

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

HEAD = "## Round 130b (2 October)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round130b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 129b" not in text:
        sys.exit("round130b: round 129b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round130b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round130b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round130b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


NOTE = '## Round 130b (2 October)\n\nNeeds round 129b. Tiles patch round130b_tiles.py beside it. No app.js?v= bump.\n\n- open_payments (geojsonlive openpay/states.geojson) after medical_culprits\n  under Suppression > The medical industry: each US state and year shaded by\n  general payments to prescribers practising there, year bar, the 50 largest\n  payers in the box and a link to every company (openpay/years/<year>.json).\n- Tiles open_payments.py: CMS\'s DKAN data service is asked for sums grouped\n  by recipient_state and paying company (expression sum/count, groupings),\n  per "<year> General Payment Data" dataset found in its metastore, so the\n  multi-GB files are never downloaded. State shapes from cgaz-boundaries USA,\n  simplified with attacks_plain.rounded. Not verified: that this DKAN accepts\n  groupings with expressions (the sandbox reaches only one plain query). If\n  build.json lists every year under "refused", the next step is the yearly\n  CSV, read in a stream.\n- Research payments and ownership interests are not added (separate files).\n\n'
DIFF = ''

if __name__ == "__main__":
    main()
